/****
 * Centralized environment accessors.
 *
 * Most functions read from EnvironmentConfig (cached at startup) and accept an
 * optional EnvironmentConfig parameter for test isolation.
 *
 * Provider env config functions (getOpenAIEnvConfig, getAnthropicEnvConfig,
 * getGoogleGenAIEnvConfig) read from getEnv() directly so they pick up
 * per-request project-scoped env vars from AsyncLocalStorage.
 *
 * @module
 */
import { getEnvironmentConfig } from "./environment-config.js";
import { getEnv } from "../platform/compat/process/env.js";
import { readVeryfrontApiTokenFile } from "../platform/cloud/credential-file.js";
function toEnabledFlag(enabled, truthyValue) {
    return enabled ? truthyValue : undefined;
}
function toCliBooleanFlag(enabled) {
    return toEnabledFlag(enabled, "1");
}
function getBaseOtelConfig(env) {
    return {
        veryfrontFlag: toCliBooleanFlag(env.otelEnabled),
        endpoint: env.otelEndpoint,
    };
}
export function getDisableLruIntervalEnv(env = getEnvironmentConfig()) {
    return env.disableLruInterval;
}
export function getApiBaseUrlEnv(env = getEnvironmentConfig()) {
    return env.apiBaseUrl;
}
export function getSsrMaxConcurrentTransformsEnv(defaultValue = 3, env = getEnvironmentConfig()) {
    return env.ssrMaxConcurrentTransforms ?? defaultValue;
}
export function getV8FlagsEnv(env = getEnvironmentConfig()) {
    return env.denoV8Flags;
}
export function getCacheDirEnv(env = getEnvironmentConfig()) {
    return env.cacheDir;
}
export function isPerfEnabledEnv(env = getEnvironmentConfig()) {
    return env.perfEnabled;
}
export function getGithubEnvConfig(env = getEnvironmentConfig()) {
    return {
        token: env.githubToken,
        owner: env.githubOwner,
        repo: env.githubRepo,
        ref: env.githubRef,
    };
}
export function getApiTokenEnv(env) {
    if (env !== undefined)
        return env.apiToken;
    const tokenFile = getEnv("VERYFRONT_API_TOKEN_FILE");
    return tokenFile !== undefined
        ? readVeryfrontApiTokenFile(tokenFile)
        : getEnvironmentConfig().apiToken;
}
export function getOpenAIEnvConfig() {
    return {
        apiKey: getEnv("OPENAI_API_KEY"),
        baseURL: getEnv("OPENAI_BASE_URL") || undefined,
    };
}
export function getAnthropicEnvConfig() {
    return {
        apiKey: getEnv("ANTHROPIC_API_KEY"),
        baseURL: getEnv("ANTHROPIC_BASE_URL") || undefined,
    };
}
export function getGoogleGenAIEnvConfig() {
    return {
        apiKey: getEnv("GOOGLE_API_KEY") || getEnv("GOOGLE_GENERATIVE_AI_API_KEY"),
        // GOOGLE_GEMINI_BASE_URL is the name Google's own gemini-cli uses for a
        // custom Gemini Developer API endpoint (proxy or regional). Vertex AI is a
        // different backend, not a base URL override: it has its own URL shape and
        // uses ADC rather than an API key.
        baseURL: getEnv("GOOGLE_GEMINI_BASE_URL") || undefined,
    };
}
export function getGoogleGenAICredentialEnvName() {
    if (getEnv("GOOGLE_API_KEY"))
        return "GOOGLE_API_KEY";
    if (getEnv("GOOGLE_GENERATIVE_AI_API_KEY"))
        return "GOOGLE_GENERATIVE_AI_API_KEY";
    return undefined;
}
export function getMistralEnvConfig() {
    return {
        apiKey: getEnv("MISTRAL_API_KEY"),
        baseURL: getEnv("MISTRAL_BASE_URL") || "https://api.mistral.ai/v1",
    };
}
export function isDebugEnvEnabled(env = getEnvironmentConfig()) {
    return env.debug;
}
export function isCiEnv(env = getEnvironmentConfig()) {
    return env.ci;
}
export function isDenoTestingEnv(env = getEnvironmentConfig()) {
    return env.denoTesting;
}
export function getNoColorEnv(env = getEnvironmentConfig()) {
    return toCliBooleanFlag(env.noColor);
}
export function getForceColorEnv(env = getEnvironmentConfig()) {
    return toCliBooleanFlag(env.forceColor);
}
export function isRscExperimentalEnabled(env = getEnvironmentConfig()) {
    return env.experimentalRsc;
}
export function getVeryfrontVersion(env = getEnvironmentConfig()) {
    return env.veryfrontVersion;
}
export function getEnvironmentFromEnv(env = getEnvironmentConfig()) {
    return env.veryfrontEnv || env.nodeEnv;
}
export function getOtelTracingConfig(env = getEnvironmentConfig()) {
    return {
        enabledFlag: toEnabledFlag(env.otelEnabled, "true"),
        ...getBaseOtelConfig(env),
        serviceName: env.otelServiceName,
        tracesEndpoint: env.otelTracesEndpoint,
        exporter: env.otelTracesExporter,
        headers: env.otelHeaders,
        tracesHeaders: undefined,
    };
}
export function getOtelMetricsConfig(env = getEnvironmentConfig()) {
    return {
        enabledFlag: toCliBooleanFlag(env.otelMetricsEnabled),
        ...getBaseOtelConfig(env),
        metricsEndpoint: env.otelMetricsEndpoint,
        exporter: env.otelMetricsExporter,
    };
}
